def parse_js_function(code):
    # Returns function representation
    code = code.strip()
    # Arrow function
    if '=>' in code:
        left, right = code.split('=>', 1)
        left = left.strip()
        right = right.strip()
        # Parse param
        if left.startswith('(') and left.endswith(')'):
            params_str = left[1:-1].strip()
            params = [p.strip() for p in params_str.split(',') if p.strip()]
        else:
            params = [left]
        # Right is body
        # If block with return
        if right.startswith('{') and right.endswith('}'):
            inner = right[1:-1].strip()
            if inner.startswith('return'):
                body = inner[6:].strip().rstrip(';')
                return {'type': 'arrow', 'params': params, 'body': body, 'is_expr': True}
            else:
                return {'type': 'arrow', 'params': params, 'body': None, 'is_expr': False}  # undefined
        else:
            # Expression
            # Handle parentheses around object literal: "({a:1})" -> "{a:1}"
            if right.startswith('(') and right.endswith(')'):
                inner = right[1:-1].strip()
                if inner.startswith('{') and inner.endswith('}'):
                    right = inner
            return {'type': 'arrow', 'params': params, 'body': right, 'is_expr': True}
    # Function expression
    m = re.match(r'function\s*\(([^)]*)\)\s*\{([^}]*)\}', code, re.DOTALL)
    if m:
        params_str = m.group(1).strip()
        body_str = m.group(2).strip()
        params = [p.strip() for p in params_str.split(',') if p.strip()] if params_str else []
        # Body should contain return
        if 'return' in body_str:
            # Extract after return
            ret_match = re.search(r'return\s+([^;]+)', body_str)
            if ret_match:
                body = ret_match.group(1).strip()
                return {'type': 'function', 'params': params, 'body': body, 'is_expr': True}
        return {'type': 'function', 'params': params, 'body': None, 'is_expr': False}
    return None

