        elif ch=='[':
            depth=1; j=pos+1
            while j<n and depth>0:
                if code[j]=='[': depth+=1
                elif code[j]==']': depth-=1
                j+=1
            if depth!=0: return None
            inner=code[pos+1:j-1].strip()
            key=eval_js_expression(inner, env_vars)
            if isinstance(current, dict):
                # key could be string or int
                if isinstance(key, str):
                    current=current.get(key, UNDEFINED)
                else:
                    current=current.get(str(key), current.get(key, UNDEFINED))
            elif isinstance(current, list):
                try: current=current[int(key)]
                except: current=UNDEFINED
            elif isinstance(current, str):
                try: current=current[int(key)]
                except: current=UNDEFINED
            else: current=UNDEFINED
            pos=j; consumed=pos
        else: break
    if consumed!=n: return None
    return current

def eval_chain(code, env_vars):
    code=code.strip()
    if not code: return None
    depth=0; in_str=False; str_char=''; first_dot=-1
    for i,c in enumerate(code):
        if in_str:
            if c==str_char and (i==0 or code[i-1]!='\\'): in_str=False
        else:
            if c in ('"',"'"): in_str=True; str_char=c
            elif c in ('(','[','{'): depth+=1
            elif c in (')',']','}'): depth-=1
            elif c=='.' and depth==0:
                first_dot=i; break
    if first_dot==-1: return None
    base_code=code[:first_dot].strip()
    rest=code[first_dot:].strip()
    try:
        current=eval_js_expression(base_code, env_vars)
    except:
        return None
    pos=0
    while pos<len(rest):
        if rest[pos]!='.': return None
        pos+=1
        m=re.match(r'^([a-zA-Z_$][a-zA-Z0-9_$]*)', rest[pos:])
        if not m: return None
        ident=m.group(1); pos+=len(ident)
        if pos<len(rest) and rest[pos]=='(':
            start=pos; depth=0; in_str=False; str_char=''; end=-1
            for i in range(pos, len(rest)):
                c=rest[i]
                if in_str:
                    if c==str_char and rest[i-1]!='\\': in_str=False
                else:
                    if c in ('"',"'"): in_str=True; str_char=c
                    elif c=='(': depth+=1
                    elif c==')':
                        depth-=1
                        if depth==0: end=i; break
            if end==-1: return None
            args_str=rest[start+1:end]; pos=end+1
            if ident=='map':
                func=parse_js_function(args_str)
                if func and isinstance(current, list):
                    current=[call_js_function(func,[item],env_vars) for item in current]
                else: current=[]
            elif ident=='filter':
                func=parse_js_function(args_str)
                if func and isinstance(current, list):
                    current=[item for item in current if call_js_function(func,[item],env_vars)]
                else: current=[]
            elif ident=='reduce':
                func_part,init_part=split_reduce_args(args_str)
                func=parse_js_function(func_part)
                init_val=eval_js_expression(init_part, env_vars) if init_part else None
                if func and isinstance(current, list):
                    acc=init_val; start_idx=0
                    if init_part is None:
                        if not current: acc=None
                        else: acc=current[0]; start_idx=1
                    for i in range(start_idx, len(current)):
                        acc=call_js_function(func,[acc, current[i]], env_vars)
                    current=acc
                else: current=None
            elif ident=='toUpperCase':
                current=current.upper() if isinstance(current,str) else str(current).upper()
            elif ident=='toLowerCase':
                current=current.lower() if isinstance(current,str) else str(current).lower()
            else:
                return None
        else:
            if ident=='length':
                if isinstance(current,(list,str,dict)): current=len(current)
                else: current=0
            else:
                if isinstance(current,dict): current=current.get(ident, UNDEFINED)
                elif isinstance(current,list):
                    if ident=='length': current=len(current)
                    else: current=UNDEFINED
                elif isinstance(current,str):
                    if ident=='length': current=len(current)
                    else: current=UNDEFINED
                else: current=UNDEFINED
            if pos<len(rest) and rest[pos]=='[':
                depth=1; j=pos+1
                while j<len(rest) and depth>0:
                    if rest[j]=='[': depth+=1
                    elif rest[j]==']': depth-=1
                    j+=1
                if depth!=0: return None
                inner=rest[pos+1:j-1].strip()
                key=eval_js_expression(inner, env_vars)
                if isinstance(current,dict):
                    current=current.get(str(key), current.get(key, UNDEFINED))
                elif isinstance(current,list):
                    try: current=current[int(key)]
                    except: current=UNDEFINED
                elif isinstance(current,str):
                    try: current=current[int(key)]
                    except: current=UNDEFINED
                else: current=UNDEFINED
                pos=j
    if pos!=len(rest):
        return None
    return current

def find_op(s, ops):
    depth=0; in_str=False; str_char=''
    for i in range(len(s)-1, -1, -1):
        c=s[i]
        if in_str:
            if c==str_char and (i==0 or s[i-1]!='\\'): in_str=False
        else:
            if c in ('"',"'"): in_str=True; str_char=c
            elif c in (')',']','}'): depth+=1
            elif c in ('(','[','{'): depth-=1
            elif depth==0:
                for op in ops:
                    if s[i:i+len(op)]==op:
                        return i,op
    return None

def eval_js_expression(expr, env_vars):
    code=expr.strip()
    if not code: return UNDEFINED
    if code in ('x','this'): return env_vars.get(code, UNDEFINED)
    if code=='null': return None
    if code=='true': return True
    if code=='false': return False
    if code=='undefined': return UNDEFINED
    if re.match(r'^-?\d+(\.\d+)?([eE][+-]?\d+)?$', code):
        try: return float(code) if ('.' in code or 'e' in code.lower()) else int(code)
        except: pass
    if (code.startswith('"') and code.endswith('"')) or (code.startswith("'") and code.endswith("'")):
        try:
            if code.startswith('"'): return json.loads(code)
            else: return code[1:-1]
        except: return code[1:-1]
    if code.startswith('[') and code.endswith(']'):
        inner=code[1:-1].strip()
        if not inner: return []
        try: return json.loads(code)
        except: return []
    if code.startswith('{') and code.endswith('}'):
        try:
            json_code=re.sub(r'([{,]\s*)([a-zA-Z_$][a-zA-Z0-9_$]*)(\s*:)', r'\1"\2"\3', code)
            json_code=json_code.replace("'",'"')
            return json.loads(json_code)
        except: return {}

    # Handle parenthesis around expression e.g., "({a:1})" -> "{a:1}"
    if code.startswith('(') and code.endswith(')'):
        inner=code[1:-1].strip()
        # If inner is object literal, return it
        if inner.startswith('{') and inner.endswith('}'):
            try:
                json_code=re.sub(r'([{,]\s*)([a-zA-Z_$][a-zA-Z0-9_$]*)(\s*:)', r'\1"\2"\3', inner)
                json_code=json_code.replace("'",'"')
                return json.loads(json_code)
            except:
                pass
        # Otherwise eval inner
        try:
            return eval_js_expression(inner, env_vars)
        except:
            pass

    chain_val=eval_chain(code, env_vars)
    if chain_val is not None:
        return chain_val

    m=re.match(r'Object\.keys\((.*)\)$', code)
    if m:
        val=eval_js_expression(m.group(1).strip(), env_vars)
        return list(val.keys()) if isinstance(val,dict) else []
    m=re.match(r'Object\.values\((.*)\)$', code)
    if m:
        val=eval_js_expression(m.group(1).strip(), env_vars)
        return list(val.values()) if isinstance(val,dict) else []
    m=re.match(r'Object\.entries\((.*)\)$', code)
    if m:
        val=eval_js_expression(m.group(1).strip(), env_vars)
        return list(val.items()) if isinstance(val,dict) else []
    m=re.match(r'JSON\.stringify\((.*)\)$', code)
    if m:
        val=eval_js_expression(m.group(1).strip(), env_vars)
        return json.dumps(val)
    m=re.match(r'JSON\.parse\((.*)\)$', code)
    if m:
        inner=m.group(1).strip()
        val=eval_js_expression(inner, env_vars)
        if isinstance(val,str):
            try: return json.loads(val)
            except: return None
        return val

    m=re.match(r"""(.+)\.toUpperCase\(\)$""", code)
    if m:
        v=eval_js_expression(m.group(1).strip(), env_vars)
        return v.upper() if isinstance(v,str) else str(v).upper() if v is not None else UNDEFINED
    m=re.match(r"""(.+)\.toLowerCase\(\)$""", code)
    if m:
        v=eval_js_expression(m.group(1).strip(), env_vars)
        return v.lower() if isinstance(v,str) else str(v).lower() if v is not None else UNDEFINED
    m=re.match(r"""(.+)\.length$""", code)
    if m:
        v=eval_js_expression(m.group(1).strip(), env_vars)
        return len(v) if isinstance(v,(list,str,dict)) else 0

    val=eval_member_chain_simple(code, env_vars)
    if val is not None:
        return val

    # Operators
    for op_list in [['||'], ['&&'], ['=='], ['!='], ['>='], ['<='], ['>'], ['<'], ['+'], ['-'], ['*'], ['/'], ['%']]:
        res=find_op(code, op_list)
        if res:
            i,op=res
            if op in ('>','<') and i+1<len(code) and code[i+1]=='=':
                continue
            if op in ('==','!=') and i+1<len(code) and code[i+1]=='=' and i+2<len(code) and code[i+2]=='=':
                # === or !==
                continue
            left=code[:i].strip()
            right=code[i+len(op):].strip()
            if not left or not right:
                continue
            try:
                lv=eval_js_expression(left, env_vars)
                rv=eval_js_expression(right, env_vars)
                if op=='||':
                    return lv if lv else rv
                if op=='&&':
                    return rv if lv else lv
                if op=='==':
                    return lv==rv
                if op=='!=':
                    return lv!=rv
                if op=='>=':
                    return lv>=rv
                if op=='<=':
                    return lv<=rv
                if op=='>':
                    return lv>rv
                if op=='<':
                    return lv<rv
                if op=='+':
                    if isinstance(lv,str) or isinstance(rv,str):
                        def js_str(v):
                            if v is None: return "null"
                            if isinstance(v, UNDEFINED.__class__): return "undefined"
                            if isinstance(v,bool): return "true" if v else "false"
                            return str(v)
                        return js_str(lv)+js_str(rv)
                    return (lv or 0)+(rv or 0)
                if op=='-':
                    return (lv or 0)-(rv or 0)
                if op=='*':
                    return (lv or 0)*(rv or 0)
                if op=='/':
                    return (lv or 0)/(rv or 0) if rv!=0 else float('inf')
                if op=='%':
                    return (lv or 0)%(rv or 0) if rv!=0 else 0
            except:
                pass

    # Try to handle === and !== and other JS specifics that we filtered earlier
    # Replace === with ==, !== with != for simple cases, but we already handled
    # Try python eval fallback with wrapper
    try:
        py_code=code.replace('===','==').replace('!==','!=')
        py_code=py_code.replace('true','True').replace('false','False').replace('null','None')
        # Use wrapper for attribute access
        class Wrapper:
            def __init__(self, data):
                self._data=data
            def __getattr__(self, name):
                if isinstance(self._data, dict):
                    return Wrapper(self._data.get(name, UNDEFINED)) if name in self._data or isinstance(self._data.get(name), (dict,list)) else self._data.get(name, UNDEFINED)
                if isinstance(self._data, list):
                    if name=='length':
                        return len(self._data)
                if isinstance(self._data, str):
                    if name=='length':
                        return len(self._data)
                return UNDEFINED
            def __getitem__(self, key):
                if isinstance(self._data, dict):
                    return self._data.get(key, UNDEFINED)
                if isinstance(self._data, list):
                    try: return self._data[key]
                    except: return UNDEFINED
                return UNDEFINED
        wrapped_x=Wrapper(env_vars.get('x'))
        wrapped_this=Wrapper(env_vars.get('this'))
        safe_env={'x': wrapped_x, 'this': wrapped_this, 'True': True, 'False': False, 'None': None}
        result=eval(py_code, {"__builtins__": {}}, safe_env)
        if isinstance(result, Wrapper):
            return result._data
        return result
    except:
        pass

    raise Exception(f"Cannot eval {code!r}")

def evaluate_code(code, input_data):
    code=code.strip()
    if not code:
        return None
    if code.startswith('.'):
        code=f"x => x{code}"
    if code in ('x','this'):
        return input_data
    func=parse_js_function(code)
    if func:
        res=call_js_function(func, [input_data], {'x':input_data,'this':input_data})
        # If function returns undefined and code was not arrow with undefined body, maybe try expression?
        return res
    env={'x':input_data,'this':input_data}
    try:
        result=eval_js_expression(code, env)
        return result
    except Exception as e:
        raise

def format_output(value):
    # Format as original fx does in pipe mode
    if value is None:
        return "null\n"
    if isinstance(value, UNDEFINED.__class__):
        return "undefined\n"
    if isinstance(value, bool):
        return "true\n" if value else "false\n"
    if isinstance(value, (int,float)):
        # Preserve int vs float? If float and is_integer, original shows int? e.g., 1 not 1.0
        # For simplicity, if it's int, print int, if float, print as is but without extra formatting
        if isinstance(value, float):
            # If it's integer-like, print int?
            if value.is_integer():
                return f"{int(value)}\n"
            return f"{value}\n"
        return f"{value}\n"
    if isinstance(value, str):
        return f"{value}\n"
    # For dict/list, pretty print with 2-space indent
    # Use json.dumps with indent=2
    # But ensure ascii? original outputs unicode as is
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"

def parse_json_with_trailing_commas(text, strict=False):
    # If strict is True, use strict json parsing (no trailing commas)
    # If not strict, allow trailing commas
    # Also need to handle multiple json objects? We'll handle elsewhere
    if strict:
        return json.loads(text)
    # Remove trailing commas: replace ",}" with "}" and ",]" with "]"
    # This is simplistic but should handle many cases
    # Use regex to remove trailing commas before } or ]
    def remove_trailing_commas(s):
        # This is a simple approach: repeatedly replace ",\s*}" with "}"
        s = re.sub(r',\s*}', '}', s)
        s = re.sub(r',\s*]', ']', s)
        return s
    cleaned = remove_trailing_commas(text)
    return json.loads(cleaned)

def parse_yaml_simple(text):
    # Try to use yaml if available, else simple parser
    try:
        import yaml
        return yaml.safe_load(text)
    except:
        # Very simple yaml parser for our tests: handles "a: 1" and nested "a:\n  b: 1"
        # We'll use a minimal implementation
        lines = text.splitlines()
        result = {}
        stack = [result]
        indent_stack = [0]
        for line in lines:
            if not line.strip() or line.strip().startswith('#'):
                continue
            indent = len(line) - len(line.lstrip())
            line_stripped = line.strip()
            if ':' in line_stripped:
                key, val = line_stripped.split(':', 1)
                key = key.strip()
                val = val.strip()
                # Adjust stack based on indent
                while indent < indent_stack[-1]:
                    stack.pop()
                    indent_stack.pop()
                if not val:
                    # New dict
                    new_dict = {}
                    if isinstance(stack[-1], dict):
                        stack[-1][key] = new_dict
                    stack.append(new_dict)
                    indent_stack.append(indent+2)
                else:
                    # Try to parse val as int, bool, etc.
                    try:
                        parsed_val = json.loads(val)
                    except:
                        # Try int
                        try:
                            if val.lower() == 'true':
                                parsed_val = True
                            elif val.lower() == 'false':
                                parsed_val = False
                            elif val.lower() == 'null':
                                parsed_val = None
                            else:
                                # Try number
                                if '.' in val:
                                    parsed_val = float(val)
                                else:
                                    parsed_val = int(val)
                        except:
                            parsed_val = val
                    if isinstance(stack[-1], dict):
                        stack[-1][key] = parsed_val
            else:
                # Not key: value
                pass
        return result

def parse_toml_simple(text):
    try:
        import tomli
        return tomli.loads(text)
    except:
        try:
            import tomllib
            return tomllib.loads(text)
        except:
            # Very simple toml for tests: "a = 1", "[table]\nkey = 'val'"
            result = {}
            current = result
            for line in text.splitlines():
                line=line.strip()
                if not line or line.startswith('#'):
                    continue
                if line.startswith('[') and line.endswith(']'):
                    table_name=line[1:-1].strip()
                    parts=table_name.split('.')
                    cur=result
                    for p in parts:
                        if p not in cur:
                            cur[p]={}
                        cur=cur[p]
                    current=cur
                elif '=' in line:
                    k,v=line.split('=',1)
                    k=k.strip()
                    v=v.strip()
                    # Parse v
                    if v.startswith('"') and v.endswith('"'):
                        try:
                            parsed=json.loads(v)
                        except:
                            parsed=v[1:-1]
                    elif v.startswith("'") and v.endswith("'"):
                        parsed=v[1:-1]
                    else:
                        try:
                            parsed=json.loads(v)
                        except:
                            try:
                                if '.' in v:
                                    parsed=float(v)
                                else:
                                    parsed=int(v)
                            except:
                                if v.lower()=='true':
                                    parsed=True
                                elif v.lower()=='false':
                                    parsed=False
                                else:
                                    parsed=v
                    current[k]=parsed
            return result

def output_error_json_parse(text, strict=False):
    # Try to produce similar error message as original
    # Original error for "not json" was:
    # Unexpected character 'o' on line 1.
    # 
    #   not json
    #   .^
    #
    # For strict trailing comma: "Trailing comma is not allowed in strict mode on line 1.\n\n  {\"a\":1,}\n  ......^\n"
    # We need to mimic
    if strict and ',}' in text or ',]' in text:
        # Check for trailing comma
        # Find line and column
        lines=text.splitlines()
        for i,line in enumerate(lines):
            # Find ",}" or ",]"
            m=re.search(r',\s*[}\]]', line)
            if m:
                col=m.start()
                # Build error
                err=f"Trailing comma is not allowed in strict mode on line {i+1}.\n\n  {line}\n  {'.'*col}^\n\n"
                return err
    # For invalid json, find first unexpected char?
    # Simplistic: use json parser error
    try:
        json.loads(text)
    except json.JSONDecodeError as e:
        line_no=e.lineno
        col_no=e.colno
        # Get line text
        lines=text.splitlines()
        if line_no-1 < len(lines):
            line_text=lines[line_no-1]
        else:
            line_text=text[:50]
        # Build caret line: spaces then ^ at col?
        # Original shows "  not json\n  .^\n" where "^" under the char
        # col_no is 1-indexed
        caret='.'*(col_no-1) + '^' if col_no>0 else '^'
        err=f"Unexpected character '{text[col_no-1] if col_no-1 < len(text) else '?'}' on line {line_no}.\n\n  {line_text}\n  {caret}\n\n"
        return err
    return f"Invalid JSON\n"

