            key=eval_js_expression(inner, env_vars)
            if isinstance(current, dict):
                current=current.get(str(key), current.get(key, UNDEFINED))
            elif isinstance(current, list):
                try: current=current[int(key)]
                except: current=UNDEFINED
            elif isinstance(current, str):
                try: current=current[int(key)]
                except: current=UNDEFINED
            else: current=UNDEFINED
            pos=j; consumed=pos
        else: break
    if consumed!=n: return None
    return current

def eval_chain(code, env_vars):
    code=code.strip()
    if not code: return None
    depth=0; in_str=False; str_char=''; first_dot=-1
    for i,c in enumerate(code):
        if in_str:
            if c==str_char and (i==0 or code[i-1]!='\\'): in_str=False
        else:
            if c in ('"',"'"): in_str=True; str_char=c
            elif c in ('(','[','{'): depth+=1
            elif c in (')',']','}'): depth-=1
            elif c=='.' and depth==0:
                first_dot=i; break
    if first_dot==-1: return None
    base_code=code[:first_dot].strip()
    rest=code[first_dot:].strip()
    try:
        current=eval_js_expression(base_code, env_vars)
    except:
        return None
    pos=0
    while pos<len(rest):
        if rest[pos]!='.': return None
        pos+=1
        m=re.match(r'^([a-zA-Z_$][a-zA-Z0-9_$]*)', rest[pos:])
        if not m: return None
        ident=m.group(1); pos+=len(ident)
        if pos<len(rest) and rest[pos]=='(':
            start=pos; depth=0; in_str=False; str_char=''; end=-1
            for i in range(pos, len(rest)):
                c=rest[i]
                if in_str:
                    if c==str_char and rest[i-1]!='\\': in_str=False
                else:
                    if c in ('"',"'"): in_str=True; str_char=c
                    elif c=='(': depth+=1
                    elif c==')':
                        depth-=1
                        if depth==0: end=i; break
            if end==-1: return None
            args_str=rest[start+1:end]; pos=end+1
            if ident=='map':
                func=parse_js_function(args_str)
                if func and isinstance(current, list):
                    current=[call_js_function(func,[item],env_vars) for item in current]
                else: current=[]
            elif ident=='filter':
                func=parse_js_function(args_str)
                if func and isinstance(current, list):
                    current=[item for item in current if call_js_function(func,[item],env_vars)]
                else: current=[]
            elif ident=='reduce':
                func_part,init_part=split_reduce_args(args_str)
                func=parse_js_function(func_part)
                init_val=eval_js_expression(init_part, env_vars) if init_part else None
                if func and isinstance(current, list):
                    acc=init_val; start_idx=0
                    if init_part is None:
                        if not current: acc=None
                        else: acc=current[0]; start_idx=1
                    for i in range(start_idx, len(current)):
                        acc=call_js_function(func,[acc, current[i]], env_vars)
                    current=acc
                else: current=None
            elif ident=='toUpperCase':
                current=current.upper() if isinstance(current,str) else str(current).upper()
            elif ident=='toLowerCase':
                current=current.lower() if isinstance(current,str) else str(current).lower()
            else:
                return None
        else:
            if ident=='length':
                if isinstance(current,(list,str,dict)): current=len(current)
                else: current=0
            else:
                if isinstance(current,dict): current=current.get(ident, UNDEFINED)
                elif isinstance(current,list):
                    if ident=='length': current=len(current)
                    else: current=UNDEFINED
                elif isinstance(current,str):
                    if ident=='length': current=len(current)
                    else: current=UNDEFINED
                else: current=UNDEFINED
            if pos<len(rest) and rest[pos]=='[':
                depth=1; j=pos+1
                while j<len(rest) and depth>0:
                    if rest[j]=='[': depth+=1
                    elif rest[j]==']': depth-=1
                    j+=1
                if depth!=0: return None
                inner=rest[pos+1:j-1].strip()
                key=eval_js_expression(inner, env_vars)
                if isinstance(current,dict):
                    current=current.get(str(key), current.get(key, UNDEFINED))
                elif isinstance(current,list):
                    try: current=current[int(key)]
                    except: current=UNDEFINED
                elif isinstance(current,str):
                    try: current=current[int(key)]
                    except: current=UNDEFINED
                else: current=UNDEFINED
                pos=j
    if pos!=len(rest):
        return None
    return current

def find_op(s, ops):
    depth=0; in_str=False; str_char=''
    for i in range(len(s)-1, -1, -1):
        c=s[i]
        if in_str:
            if c==str_char and (i==0 or s[i-1]!='\\'): in_str=False
        else:
            if c in ('"',"'"): in_str=True; str_char=c
            elif c in (')',']','}'): depth+=1
            elif c in ('(','[','{'): depth-=1
            elif depth==0:
                for op in ops:
                    if s[i:i+len(op)]==op:
                        return i,op
    return None

def eval_js_expression(expr, env_vars):
    code=expr.strip()
    if not code: return UNDEFINED
    if code in ('x','this'): return env_vars.get(code, UNDEFINED)
    if code=='null': return None
    if code=='true': return True
    if code=='false': return False
    if code=='undefined': return UNDEFINED
    if re.match(r'^-?\d+(\.\d+)?([eE][+-]?\d+)?$', code):
        try: return float(code) if ('.' in code or 'e' in code.lower()) else int(code)
        except: pass
    if (code.startswith('"') and code.endswith('"')) or (code.startswith("'") and code.endswith("'")):
        try:
            if code.startswith('"'): return json.loads(code)
            else: return code[1:-1]
        except: return code[1:-1]
    if code.startswith('[') and code.endswith(']'):
        inner=code[1:-1].strip()
        if not inner: return []
        try: return json.loads(code)
        except: return []
    if code.startswith('{') and code.endswith('}'):
        try:
            json_code=re.sub(r'([{,]\s*)([a-zA-Z_$][a-zA-Z0-9_$]*)(\s*:)', r'\1"\2"\3', code)
            json_code=json_code.replace("'",'"')
            return json.loads(json_code)
        except: return {}
    if code.startswith('(') and code.endswith(')'):
        inner=code[1:-1].strip()
        if inner.startswith('{') and inner.endswith('}'):
            try:
                json_code=re.sub(r'([{,]\s*)([a-zA-Z_$][a-zA-Z0-9_$]*)(\s*:)', r'\1"\2"\3', inner)
                json_code=json_code.replace("'",'"')
                return json.loads(json_code)
            except: pass
        try: return eval_js_expression(inner, env_vars)
        except: pass

    chain_val=eval_chain(code, env_vars)
    if chain_val is not None:
        return chain_val

    m=re.match(r'Object\.keys\((.*)\)$', code)
    if m:
        val=eval_js_expression(m.group(1).strip(), env_vars)
        return list(val.keys()) if isinstance(val,dict) else []
    m=re.match(r'Object\.values\((.*)\)$', code)
    if m:
        val=eval_js_expression(m.group(1).strip(), env_vars)
        return list(val.values()) if isinstance(val,dict) else []
    m=re.match(r'Object\.entries\((.*)\)$', code)
    if m:
        val=eval_js_expression(m.group(1).strip(), env_vars)
        return list(val.items()) if isinstance(val,dict) else []
    m=re.match(r'JSON\.stringify\((.*)\)$', code)
    if m:
        val=eval_js_expression(m.group(1).strip(), env_vars)
        return json.dumps(val)
    m=re.match(r'JSON\.parse\((.*)\)$', code)
    if m:
        inner=m.group(1).strip()
        val=eval_js_expression(inner, env_vars)
        if isinstance(val,str):
            try: return json.loads(val)
            except: return None
        return val

    m=re.match(r"""(.+)\.toUpperCase\(\)$""", code)
    if m:
        v=eval_js_expression(m.group(1).strip(), env_vars)
        return v.upper() if isinstance(v,str) else str(v).upper() if v is not None else UNDEFINED
    m=re.match(r"""(.+)\.toLowerCase\(\)$""", code)
    if m:
        v=eval_js_expression(m.group(1).strip(), env_vars)
        return v.lower() if isinstance(v,str) else str(v).lower() if v is not None else UNDEFINED
    m=re.match(r"""(.+)\.length$""", code)
    if m:
        v=eval_js_expression(m.group(1).strip(), env_vars)
        return len(v) if isinstance(v,(list,str,dict)) else 0

    val=eval_member_chain_simple(code, env_vars)
    if val is not None:
        return val

    for op_list in [['||'], ['&&'], ['=='], ['!='], ['>='], ['<='], ['>'], ['<'], ['+'], ['-'], ['*'], ['/'], ['%']]:
        res=find_op(code, op_list)
        if res:
            i,op=res
            if op in ('>','<') and i+1<len(code) and code[i+1]=='=': continue
            if op in ('==','!=') and i+2<len(code) and code[i+2]=='=': continue
            left=code[:i].strip()
            right=code[i+len(op):].strip()
            if not left or not right: continue
            try:
                lv=eval_js_expression(left, env_vars)
                rv=eval_js_expression(right, env_vars)
                if op=='||': return lv if lv else rv
                if op=='&&': return rv if lv else lv
                if op=='==': return lv==rv
                if op=='!=': return lv!=rv
                if op=='>=': return lv>=rv
                if op=='<=': return lv<=rv
                if op=='>': return lv>rv
                if op=='<': return lv<rv
                if op=='+':
                    if isinstance(lv,str) or isinstance(rv,str):
                        def js_str(v):
                            if v is None: return "null"
                            if isinstance(v, UNDEFINED.__class__): return "undefined"
                            if isinstance(v,bool): return "true" if v else "false"
                            return str(v)
                        return js_str(lv)+js_str(rv)
                    return (lv or 0)+(rv or 0)
                if op=='-': return (lv or 0)-(rv or 0)
                if op=='*': return (lv or 0)*(rv or 0)
                if op=='/': return (lv or 0)/(rv or 0) if rv!=0 else float('inf')
                if op=='%': return (lv or 0)%(rv or 0) if rv!=0 else 0
            except: pass

    raise Exception(f"Cannot eval {code!r}")

def evaluate_code(code, input_data):
    code=code.strip()
    if not code:
        return None
    # Special case: "." alone means identity
    if code == ".":
        return input_data
    if code.startswith('.'):
        # ".a" -> "x => x.a", but "." already handled
        code=f"x => x{code}"
    if code in ('x','this'):
        return input_data
    func=parse_js_function(code)
    if func:
        return call_js_function(func, [input_data], {'x':input_data,'this':input_data})
    env={'x':input_data,'this':input_data}
    try:
        result=eval_js_expression(code, env)
        return result
    except Exception as e:
        raise

def format_output(value):
    if value is None:
        return "null\n"
    if isinstance(value, UNDEFINED.__class__):
        return "undefined\n"
    if isinstance(value, bool):
        return "true\n" if value else "false\n"
    if isinstance(value, (int,float)):
        if isinstance(value, float):
            if value.is_integer():
                return f"{int(value)}\n"
            return f"{value}\n"
        return f"{value}\n"
    if isinstance(value, str):
        return f"{value}\n"
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"

def parse_json_with_trailing_commas(text, strict=False):
    if strict:
        return json.loads(text)
    def remove_trailing_commas(s):
        s=re.sub(r',\s*}', '}', s)
        s=re.sub(r',\s*]', ']', s)
        return s
    cleaned=remove_trailing_commas(text)
    return json.loads(cleaned)

def parse_yaml_simple(text):
    try:
        import yaml
        return yaml.safe_load(text)
    except:
        lines=text.splitlines()
        result={}; stack=[result]; indent_stack=[0]
        for line in lines:
            if not line.strip() or line.strip().startswith('#'): continue
            indent=len(line)-len(line.lstrip())
            line_stripped=line.strip()
            if ':' in line_stripped:
                key,val=line_stripped.split(':',1)
                key=key.strip(); val=val.strip()
                while indent < indent_stack[-1]:
                    stack.pop(); indent_stack.pop()
                if not val:
                    new_dict={}
                    if isinstance(stack[-1], dict):
                        stack[-1][key]=new_dict
                    stack.append(new_dict); indent_stack.append(indent+2)
                else:
                    try: parsed_val=json.loads(val)
                    except:
                        try:
                            if val.lower()=='true': parsed_val=True
                            elif val.lower()=='false': parsed_val=False
                            elif val.lower()=='null': parsed_val=None
                            else:
                                parsed_val=float(val) if '.' in val else int(val)
                        except:
                            parsed_val=val
                    if isinstance(stack[-1], dict):
                        stack[-1][key]=parsed_val
        return result

def parse_toml_simple(text):
    try:
        import tomli
        return tomli.loads(text)
    except:
        try:
            import tomllib
            return tomllib.loads(text)
        except:
            result={}; current=result
            for line in text.splitlines():
                line=line.strip()
                if not line or line.startswith('#'): continue
                if line.startswith('[') and line.endswith(']'):
                    table_name=line[1:-1].strip()
                    parts=table_name.split('.')
                    cur=result
                    for p in parts:
                        if p not in cur: cur[p]={}
                        cur=cur[p]
                    current=cur
                elif '=' in line:
                    k,v=line.split('=',1)
                    k=k.strip(); v=v.strip()
                    if v.startswith('"') and v.endswith('"'):
                        try: parsed=json.loads(v)
                        except: parsed=v[1:-1]
                    elif v.startswith("'") and v.endswith("'"):
                        parsed=v[1:-1]
                    else:
                        try: parsed=json.loads(v)
                        except:
                            try:
                                parsed=float(v) if '.' in v else int(v)
                            except:
                                parsed=True if v.lower()=='true' else False if v.lower()=='false' else v
                    current[k]=parsed
            return result

def output_error_json_parse(text, strict=False):
    if strict and (',}' in text or ',]' in text):
        lines=text.splitlines()
        for i,line in enumerate(lines):
            m=re.search(r',\s*[}\]]', line)
            if m:
                col=m.start()
                return f"Trailing comma is not allowed in strict mode on line {i+1}.\n\n  {line}\n  {'.'*col}^\n\n"
    try:
        json.loads(text)
    except json.JSONDecodeError as e:
        line_no=e.lineno
        col_no=e.colno
        lines=text.splitlines()
        line_text=lines[line_no-1] if line_no-1 < len(lines) else text[:50]
        caret='.'*(col_no-1) + '^' if col_no>0 else '^'
        ch=text[col_no-1] if col_no-1 < len(text) else '?'
        # For original, for "not json", it shows "Unexpected character 'o' on line 1."
        # e.msg might contain info, but we produce similar
        return f"Unexpected character '{ch}' on line {line_no}.\n\n  {line_text}\n  {caret}\n\n"
    return "Invalid JSON\n"

def list_files(prefix=""):
    return []

def complete_files(prefix):
    results=[]
    if '/' in prefix:
        dir_part=os.path.dirname(prefix)
        base=os.path.basename(prefix)
        dir_to_list=dir_part if dir_part else '.'
        try: entries=os.listdir(dir_to_list)
        except: entries=[]
        for e in entries:
            if e.startswith(base):
                full_path=os.path.join(dir_part, e) if dir_part else e
                is_dir=os.path.isdir(os.path.join(dir_to_list, e))
                if is_dir:
                    results.append((e+'/', full_path+'/' if not full_path.endswith('/') else full_path, 'file'))
                else:
                    results.append((e, full_path, 'file'))
    else:
        base=prefix
        try: entries=os.listdir('.')
        except: entries=[]
        for e in entries:
            if e.startswith(base):
                is_dir=os.path.isdir(e)
                if is_dir:
                    results.append((e+'/', e, 'file'))
                else:
                    results.append((e, e, 'file'))
    return results

def complete_keys_for_file(filepath, prefix):
    try:
        with open(filepath, 'r') as f:
            content=f.read()
        try:
            data=json.loads(content)
        except:
            try:
                data=parse_json_with_trailing_commas(content, strict=False)
            except:
                return []
    except:
        return []
    prefix=prefix.strip()
    if not prefix.startswith('.'):
        return []
    path_str=prefix[1:]
    if path_str=="":
        parent_path=[]; filter_prefix=""
    else:
        if path_str.endswith('.'):
            parts=path_str[:-1].split('.')
            parts=[p for p in parts if p!=""]
            parent_path=parts
            filter_prefix=""
        else:
            parts=path_str.split('.')
            if len(parts)==1:
                parent_path=[]; filter_prefix=parts[0]
            else:
                parent_path=parts[:-1]; filter_prefix=parts[-1]
    cur=data
    for p in parent_path:
        if isinstance(cur, dict):
            cur=cur.get(p)
            if cur is None:
                return []
        elif isinstance(cur, list):
            try: cur=cur[int(p)]
            except: return []
        else: return []
    if not isinstance(cur, dict):
        return []
    results=[]
    for k in cur.keys():
        if k.startswith(filter_prefix):
            full_path="." + ".".join(parent_path + [k]) if parent_path else "."+k
            short_display="." + k
            results.append((short_display, full_path, 'key'))
    return results

def complete_flags(prefix):
    flags=["--help","--raw","--slurp","--themes","--version","--yaml","--toml","--strict","--no-inline","--game-of-life","-h","-v","-r","-s"]
    results=[]
    for f in flags:
        if f.startswith(prefix):
            results.append((f,f,'flag'))
    return results

def handle_completion():
    comp_zsh=os.getenv('COMP_ZSH')
    comp_fish=os.getenv('COMP_FISH')
    comp_line=os.getenv('COMP_LINE')
    comp_point=os.getenv('COMP_POINT')
    if comp_zsh is not None:
        line=comp_zsh
        has_trailing_space=line.endswith(' ') or line.endswith('\t')
        parts=line.strip().split()
        if not parts:
            cur=""; prev=""
        else:
            if has_trailing_space:
                cur=""
                prev=parts[-1] if len(parts)>=2 else parts[0]
            else:
                cur=parts[-1] if parts else ""
                prev=parts[-2] if len(parts)>=2 else ""
        if cur.startswith('-'):
            comps=complete_flags(cur)
            for display,value,typ in comps:
                sys.stdout.write(f"{display}\t{value}\t{typ}\n")
            return
        prev_is_file=os.path.isfile(prev) or os.path.isfile(os.path.join('.', prev))
        if prev_is_file and (cur.startswith('.') or cur==""):
            completion_prefix=cur if cur.startswith('.') else "."
            comps=complete_keys_for_file(prev, completion_prefix)
            for display,value,typ in comps:
                sys.stdout.write(f"{display}\t{value}\t{typ}\n")
            return
        else:
            comps=complete_files(cur)
            for display,value,typ in comps:
                sys.stdout.write(f"{display}\t{value}\t{typ}\n")
            return
    if comp_fish is not None:
        line=comp_fish
        has_trailing_space=line.endswith(' ') or line.endswith('\t')
        parts=line.strip().split()
        if not parts:
            cur=""; prev=""
        else:
            if has_trailing_space:
                cur=""; prev=parts[-1] if len(parts)>=2 else parts[0]
            else:
                cur=parts[-1] if parts else ""; prev=parts[-2] if len(parts)>=2 else ""
        if cur.startswith('-'):
            comps=complete_flags(cur)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
        prev_is_file=os.path.isfile(prev)
        if prev_is_file and (cur.startswith('.') or cur==""):
            completion_prefix=cur if cur.startswith('.') else "."
            comps=complete_keys_for_file(prev, completion_prefix)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
        else:
            comps=complete_files(cur)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
    if comp_line is not None:
        cur=""; prev=""
        if len(sys.argv)>=4 and sys.argv[1]=="fx":
            cur=sys.argv[2]; prev=sys.argv[3]
        elif len(sys.argv)>=3 and sys.argv[1]=="fx":
            cur=sys.argv[2]; prev=sys.argv[1]
        else:
            line=comp_line
            try: point=int(comp_point) if comp_point else len(line)
            except: point=len(line)
            line_at_point=line[:point]
            has_trailing_space=line_at_point.endswith(' ') or line_at_point.endswith('\t')
            parts=line_at_point.strip().split()
            if not parts:
                cur=""; prev=""
            else:
                if has_trailing_space:
                    cur=""; prev=parts[-1] if len(parts)>=2 else parts[0]
                else:
                    cur=parts[-1] if parts else ""; prev=parts[-2] if len(parts)>=2 else ""
        if cur.startswith('-'):
            comps=complete_flags(cur)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
        prev_is_file=os.path.isfile(prev)
        if prev_is_file and (cur.startswith('.') or cur==""):
            completion_prefix=cur if cur.startswith('.') else "."
            comps=complete_keys_for_file(prev, completion_prefix)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
        else:
            comps=complete_files(cur)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
    if len(sys.argv)>=2 and sys.argv[1]=="fx":
        return

def main():
    if os.getenv('COMP_ZSH') is not None or os.getenv('COMP_FISH') is not None or os.getenv('COMP_LINE') is not None:
        handle_completion()
        return
    args=sys.argv[1:]
    raw=False; slurp=False; yaml_mode=False; toml_mode=False; strict=False; no_inline=False; themes=False; version=False; help_flag=False; comp_shell=None; game_of_life=False
    remaining_args=[]; i=0
    while i < len(args):
        arg=args[i]
        if arg in ('-h','--help'):
            help_flag=True; i+=1
        elif arg in ('-v','--version'):
            version=True; i+=1
        elif arg=='--themes':
            themes=True; i+=1
        elif arg=='--comp':
            if i+1 < len(args):
                comp_shell=args[i+1]; i+=2
            else:
                print(f"flag needs an argument: -comp\nUsage of {sys.argv[0]}:\n  -comp string\n    \t\n", file=sys.stderr)
                sys.exit(2)
        elif arg.startswith('--comp='):
            comp_shell=arg.split('=',1)[1]; i+=1
        elif arg in ('-r','--raw'):
            raw=True; i+=1
        elif arg in ('-s','--slurp'):
            slurp=True; i+=1
        elif arg=='--yaml':
            yaml_mode=True; i+=1
        elif arg=='--toml':
            toml_mode=True; i+=1
        elif arg=='--strict':
