        for i,c in enumerate(code):
            if in_str:
                if c==str_char and code[i-1]!='\\': in_str=False
            else:
                if c in ('"',"'"): in_str=True; str_char=c
                elif c in ('(','[','{'): depth+=1
                elif c in (')',']','}'): depth-=1
