            elif c in (')',']','}'): depth-=1
            elif c==',' and depth==0: last_comma=i
    if last_comma==-1: return s,None
    return s[:last_comma].strip(), s[last_comma+1:].strip()

def call_js_function(func, args, env_vars):
    if not func: return UNDEFINED
