    if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$', code):
        raise JSReferenceError(code)

    raise Exception(f"Cannot eval {code!r}")

def evaluate_code(code, input_data):
    code=code.strip()
    if not code: return None
    if code == ".": return input_data
    if code.startswith('.'):
        code=f"x => x{code}"
    if code in ('x','this'): return input_data
    func=parse_js_function(code)
    if func:
        return call_js_function(func, [input_data], {'x':input_data,'this':input_data})
    env={'x':input_data,'this':input_data}
    try:
        result=eval_js_expression(code, env)
        return result
    except Exception as e:
        raise

def format_output(value):
    if value is None: return "null\n"
    if isinstance(value, UNDEFINED.__class__): return "undefined\n"
    if isinstance(value, bool): return "true\n" if value else "false\n"
    if isinstance(value, (int,float)):
        if isinstance(value, float):
            if value.is_integer(): return f"{int(value)}\n"
            return f"{value}\n"
        return f"{value}\n"
    if isinstance(value, str): return f"{value}\n"
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"

def parse_json_with_trailing_commas(text, strict=False):
    if strict:
        return json.loads(text)
    def remove_trailing_commas(s):
        s=re.sub(r',\s*}', '}', s)
        s=re.sub(r',\s*]', ']', s)
        return s
    cleaned=remove_trailing_commas(text)
    return json.loads(cleaned)

def parse_yaml_simple(text):
    try:
        import yaml
        return yaml.safe_load(text)
    except:
        lines=text.splitlines()
        result={}; stack=[result]; indent_stack=[0]
        for line in lines:
            if not line.strip() or line.strip().startswith('#'): continue
            indent=len(line)-len(line.lstrip())
            line_stripped=line.strip()
            if ':' in line_stripped:
                key,val=line_stripped.split(':',1)
                key=key.strip(); val=val.strip()
                while indent < indent_stack[-1]:
                    stack.pop(); indent_stack.pop()
                if not val:
                    new_dict={}
                    if isinstance(stack[-1], dict):
                        stack[-1][key]=new_dict
                    stack.append(new_dict); indent_stack.append(indent+2)
                else:
                    try: parsed_val=json.loads(val)
                    except:
                        try:
                            if val.lower()=='true': parsed_val=True
                            elif val.lower()=='false': parsed_val=False
                            elif val.lower()=='null': parsed_val=None
                            else: parsed_val=float(val) if '.' in val else int(val)
                        except:
                            parsed_val=val
                    if isinstance(stack[-1], dict):
                        stack[-1][key]=parsed_val
        return result

def parse_toml_simple(text):
    try:
        import tomli
        return tomli.loads(text)
    except:
        try:
            import tomllib
            return tomllib.loads(text)
        except:
            result={}; current=result
            for line in text.splitlines():
                line=line.strip()
                if not line or line.startswith('#'): continue
                if line.startswith('[') and line.endswith(']'):
                    table_name=line[1:-1].strip()
                    parts=table_name.split('.')
                    cur=result
                    for p in parts:
                        if p not in cur: cur[p]={}
                        cur=cur[p]
                    current=cur
                elif '=' in line:
                    k,v=line.split('=',1)
                    k=k.strip(); v=v.strip()
                    if v.startswith('"') and v.endswith('"'):
                        try: parsed=json.loads(v)
                        except: parsed=v[1:-1]
                    elif v.startswith("'") and v.endswith("'"):
                        parsed=v[1:-1]
                    else:
                        try: parsed=json.loads(v)
                        except:
                            try: parsed=float(v) if '.' in v else int(v)
                            except: parsed=True if v.lower()=='true' else False if v.lower()=='false' else v
                    current[k]=parsed
            return result

def output_error_json_parse(text, strict=False):
    if strict:
        lines=text.splitlines()
        for i,line in enumerate(lines):
            m=re.search(r',\s*[}\]]', line)
            if m:
                col=m.start()
                return f"Trailing comma is not allowed in strict mode on line {i+1}.\n\n  {line}\n  {'.'*col}^\n\n"
    try:
        json.loads(text)
    except json.JSONDecodeError as e:
        line_no=e.lineno; col_no=e.colno
        lines=text.splitlines()
        line_text=lines[line_no-1] if line_no-1 < len(lines) else text[:50]
        caret='.'*(col_no-1) + '^' if col_no>0 else '^'
        ch=text[col_no-1] if 0 <= col_no-1 < len(text) else '?'
        return f"Unexpected character '{ch}' on line {line_no}.\n\n  {line_text}\n  {caret}\n\n"
    return "Invalid JSON\n"

def complete_files(prefix):
    results=[]
    if '/' in prefix:
        dir_part=os.path.dirname(prefix)
        base=os.path.basename(prefix)
        dir_to_list=dir_part if dir_part else '.'
        try: entries=os.listdir(dir_to_list)
        except: entries=[]
        for e in sorted(entries):
            if e.startswith(base):
                full_path=os.path.join(dir_part, e) if dir_part else e
                is_dir=os.path.isdir(os.path.join(dir_to_list, e))
                if is_dir:
                    results.append((e+'/', full_path+'/', 'file'))
                else:
                    results.append((e, full_path, 'file'))
    else:
        base=prefix
        try: entries=os.listdir('.')
        except: entries=[]
        for e in sorted(entries):
            if e.startswith(base):
                is_dir=os.path.isdir(e)
                if is_dir:
                    results.append((e+'/', e, 'file'))
                else:
                    results.append((e, e, 'file'))
    return results

def complete_keys_for_file(filepath, prefix):
    try:
        with open(filepath, 'r') as f:
            content=f.read()
        try: data=json.loads(content)
        except:
            try: data=parse_json_with_trailing_commas(content, strict=False)
            except: return []
    except: return []
    prefix=prefix.strip()
    if not prefix.startswith('.'): return []
    path_str=prefix[1:]
    if path_str=="":
        parent_path=[]; filter_prefix=""
    else:
        if path_str.endswith('.'):
            parts=path_str[:-1].split('.')
            parts=[p for p in parts if p!=""]
            parent_path=parts; filter_prefix=""
        else:
            parts=path_str.split('.')
            if len(parts)==1:
                parent_path=[]; filter_prefix=parts[0]
            else:
                parent_path=parts[:-1]; filter_prefix=parts[-1]
    cur=data
    for p in parent_path:
        if isinstance(cur, dict):
            cur=cur.get(p)
            if cur is None: return []
        elif isinstance(cur, list):
            try: cur=cur[int(p)]
            except: return []
        else: return []
    if not isinstance(cur, dict): return []
    results=[]
    for k in cur.keys():
        if k.startswith(filter_prefix):
            full_path="." + ".".join(parent_path + [k]) if parent_path else "."+k
            short_display="." + k
            results.append((short_display, full_path, 'key'))
    return results

def complete_flags(prefix):
    flags=["--help","--raw","--slurp","--themes","--version","--yaml","--toml","--strict","--no-inline"]
    results=[]
    for f in flags:
        if f.startswith(prefix):
            results.append((f,f,'flag'))
    if prefix=="-" or (prefix.startswith("-") and not prefix.startswith("--")):
        short_flags=["-h","-v","-r","-s"]
        for f in short_flags:
            if f.startswith(prefix):
                if f not in [x[0] for x in results]:
                    results.append((f,f,'flag'))
        if prefix=="-":
            for f in flags:
                if f not in [x[0] for x in results]:
                    results.append((f,f,'flag'))
    return results

def handle_completion():
    comp_zsh=os.getenv('COMP_ZSH')
    comp_fish=os.getenv('COMP_FISH')
    comp_line=os.getenv('COMP_LINE')
    comp_point=os.getenv('COMP_POINT')
    if comp_zsh is not None:
        line=comp_zsh
        has_trailing_space=line.endswith(' ') or line.endswith('\t')
        parts=line.strip().split()
        if not parts:
            cur=""; prev=""
        else:
            if has_trailing_space:
                cur=""; prev=parts[-1] if len(parts)>=2 else parts[0]
            else:
                cur=parts[-1] if parts else ""; prev=parts[-2] if len(parts)>=2 else ""
        if cur.startswith('-'):
            comps=complete_flags(cur)
            for display,value,typ in comps:
                sys.stdout.write(f"{display}\t{value}\t{typ}\n")
            return
        prev_is_file=os.path.isfile(prev) or os.path.isfile(os.path.join('.', prev))
        if prev_is_file and (cur.startswith('.') or cur==""):
            completion_prefix=cur if cur.startswith('.') else "."
            comps=complete_keys_for_file(prev, completion_prefix)
            for display,value,typ in comps:
                sys.stdout.write(f"{display}\t{value}\t{typ}\n")
            return
        else:
            comps=complete_files(cur)
            for display,value,typ in comps:
                sys.stdout.write(f"{display}\t{value}\t{typ}\n")
            return
    if comp_fish is not None:
        line=comp_fish
        has_trailing_space=line.endswith(' ') or line.endswith('\t')
        parts=line.strip().split()
        if not parts:
            cur=""; prev=""
        else:
            if has_trailing_space:
                cur=""; prev=parts[-1] if len(parts)>=2 else parts[0]
            else:
                cur=parts[-1] if parts else ""; prev=parts[-2] if len(parts)>=2 else ""
        if cur.startswith('-'):
            comps=complete_flags(cur)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
        prev_is_file=os.path.isfile(prev)
        if prev_is_file and (cur.startswith('.') or cur==""):
            completion_prefix=cur if cur.startswith('.') else "."
            comps=complete_keys_for_file(prev, completion_prefix)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
        else:
            comps=complete_files(cur)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
    if comp_line is not None:
        cur=""; prev=""
        if len(sys.argv)>=4 and sys.argv[1]=="fx":
            cur=sys.argv[2]; prev=sys.argv[3]
        elif len(sys.argv)>=3 and sys.argv[1]=="fx":
            cur=sys.argv[2]; prev=sys.argv[1]
        else:
            line=comp_line
            try: point=int(comp_point) if comp_point else len(line)
            except: point=len(line)
            line_at_point=line[:point]
            has_trailing_space=line_at_point.endswith(' ') or line_at_point.endswith('\t')
            parts=line_at_point.strip().split()
            if not parts:
                cur=""; prev=""
            else:
                if has_trailing_space:
                    cur=""; prev=parts[-1] if len(parts)>=2 else parts[0]
                else:
                    cur=parts[-1] if parts else ""; prev=parts[-2] if len(parts)>=2 else ""
        if cur.startswith('-'):
            comps=complete_flags(cur)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
        prev_is_file=os.path.isfile(prev)
        if prev_is_file and (cur.startswith('.') or cur==""):
            completion_prefix=cur if cur.startswith('.') else "."
            comps=complete_keys_for_file(prev, completion_prefix)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
        else:
            comps=complete_files(cur)
            for _,value,typ in comps:
                sys.stdout.write(f"{value}\n")
            return
    if len(sys.argv)>=2 and sys.argv[1]=="fx":
        return

def main():
    if os.getenv('COMP_ZSH') is not None or os.getenv('COMP_FISH') is not None or os.getenv('COMP_LINE') is not None:
        handle_completion()
        return
    args=sys.argv[1:]
    raw=False; slurp=False; yaml_mode=False; toml_mode=False; strict=False; no_inline=False; themes=False; version=False; help_flag=False; comp_shell=None; game_of_life=False
    remaining_args=[]; i=0
    while i < len(args):
        arg=args[i]
        if arg in ('-h','--help'):
            help_flag=True; i+=1
        elif arg in ('-v','--version'):
            version=True; i+=1
        elif arg=='--themes':
            themes=True; i+=1
        elif arg=='--comp':
            if i+1 < len(args):
                comp_shell=args[i+1]; i+=2
            else:
                print(f"flag needs an argument: -comp\nUsage of {sys.argv[0]}:\n  -comp string\n    \t\n", file=sys.stderr)
                sys.exit(2)
        elif arg.startswith('--comp='):
            comp_shell=arg.split('=',1)[1]; i+=1
        elif arg in ('-r','--raw'):
            raw=True; i+=1
        elif arg in ('-s','--slurp'):
            slurp=True; i+=1
        elif arg=='--yaml':
            yaml_mode=True; i+=1
        elif arg=='--toml':
            toml_mode=True; i+=1
        elif arg=='--strict':
            strict=True; i+=1
        elif arg=='--no-inline':
            no_inline=True; i+=1
        elif arg=='--game-of-life':
            game_of_life=True; i+=1
        elif arg.startswith('-'):
            remaining_args.append(arg); i+=1
        else:
            remaining_args.append(arg); i+=1

    if help_flag:
        sys.stdout.write(HELP_TEXT)
        return
    if version:
        sys.stdout.write(f"{VERSION}\n")
        return
    if themes:
        for th in THEMES:
            sys.stdout.write(f'export FX_THEME="{th}"\n')
            sys.stdout.write(THEME_SAMPLE_JSON + "\n")
            sys.stdout.write("\n")
        return
    if comp_shell is not None:
        if comp_shell=="bash":
            sys.stdout.write(COMP_BASH)
            return
        elif comp_shell=="zsh":
            sys.stdout.write(COMP_ZSH + "\n")
            return
        elif comp_shell=="fish":
            sys.stdout.write(COMP_FISH)
            return
        else:
            sys.stdout.write("unknown shell type\n")
            return
    if game_of_life:
        import time, random
        width=80; height=24
        grid=[[0]*width for _ in range(height)]
        grid[1][2]=1; grid[2][3]=1; grid[3][1]=1; grid[3][2]=1; grid[3][3]=1
        for _ in range(100):
            grid[random.randint(0,height-1)][random.randint(0,width-1)]=1
        def draw(g):
            out="\033[2J\033[H"
            for y in range(height):
                line=""
                for x in range(width):
                    line+= "█" if g[y][x] else " "
                out+=line+"\n"
            sys.stdout.write(out)
            sys.stdout.flush()
        try:
            while True:
                draw(grid)
                new_grid=[[0]*width for _ in range(height)]
                for y in range(height):
                    for x in range(width):
                        count=0
                        for dy in (-1,0,1):
                            for dx in (-1,0,1):
                                if dy==0 and dx==0: continue
                                ny=y+dy; nx=x+dx
                                if 0 <= ny < height and 0 <= nx < width:
                                    count+=grid[ny][nx]
                        if grid[y][x]==1:
                            if count==2 or count==3:
                                new_grid[y][x]=1
                        else:
                            if count==3:
                                new_grid[y][x]=1
                grid=new_grid
                time.sleep(0.1)
        except KeyboardInterrupt:
            sys.stdout.write("\033[?25h\033[?1049l")
            return
        except:
            draw(grid)
            return

    stdin_is_tty=sys.stdin.isatty()
    stdout_is_tty=sys.stdout.isatty()
    stdin_data=""; stdin_has_data=False
    if not stdin_is_tty:
        try:
            data=sys.stdin.read()
            stdin_data=data
            if data.strip() != "":
                stdin_has_data=True
        except:
            stdin_data=""; stdin_has_data=False
    else:
        stdin_data=""; stdin_has_data=False

    if not remaining_args and not stdin_has_data:
        if stdin_is_tty:
            sys.stdout.write(HELP_TEXT)
            return
        else:
            sys.stderr.write("panic: could not open a new TTY: open /dev/tty: no such device or address\n\n")
            sys.stderr.write("goroutine 1 [running]:\n")
            sys.stderr.write("main.main()\n")
            sys.stderr.write("\tgithub.com/antonmedv/fx/main.go:317 +0x191e\n")
            sys.exit(2)

    files=[]; code_parts=[]
    if stdin_has_data:
        code_parts=remaining_args
        files=[]
    else:
        for arg in remaining_args:
            if os.path.isfile(arg):
                files.append(arg)
            else:
                code_parts.append(arg)

    def read_file_content(filepath):
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            return f.read()

    def parse_input_text(text, raw, yaml_mode, toml_mode, strict):
        text=text.strip()
        if not text:
            return []
        if raw:
            lines=text.splitlines()
            return lines
        if yaml_mode:
            try:
                data=parse_yaml_simple(text)
                return [data]
            except Exception as e:
                raise
        if toml_mode:
            try:
                data=parse_toml_simple(text)
                return [data]
            except Exception as e:
                raise
        try:
            data=parse_json_with_trailing_commas(text, strict=strict)
            return [data]
        except:
            results=[]
            for line in text.splitlines():
                line=line.strip()
                if not line: continue
                try:
                    data=parse_json_with_trailing_commas(line, strict=strict)
                    results.append(data)
                except:
                    raise
            return results

    input_list=[]
    if files:
        for fp in files:
            try:
                content=read_file_content(fp)
                parsed=parse_input_text(content, raw, yaml_mode, toml_mode, strict)
                input_list.extend(parsed)
            except FileNotFoundError:
                sys.stderr.write(f"open {fp}: no such file or directory\n")
                sys.exit(1)
            except Exception as e:
                if not yaml_mode and not toml_mode:
                    err_text=output_error_json_parse(content, strict)
                    sys.stderr.write(err_text)
                    sys.exit(1)
                else:
                    sys.stderr.write(f"{e}\n")
                    sys.exit(1)
    else:
        if stdin_has_data:
            try:
                parsed=parse_input_text(stdin_data, raw, yaml_mode, toml_mode, strict)
                input_list.extend(parsed)
            except Exception as e:
                if not yaml_mode and not toml_mode:
                    err_text=output_error_json_parse(stdin_data, strict)
                    sys.stderr.write(err_text)
                    sys.exit(1)
                else:
                    sys.stderr.write(f"{e}\n")
                    sys.exit(1)
        else:
            input_list=[]

    if slurp:
        slurped_data=input_list
        input_list=[slurped_data]

    code_str=" ".join(code_parts) if code_parts else ""

    if not code_str:
        if stdin_has_data and not files:
            sys.stderr.write("panic: could not open a new TTY: open /dev/tty: no such device or address\n\n")
            sys.stderr.write("goroutine 1 [running]:\n")
            sys.stderr.write("main.main()\n")
            sys.stderr.write("\tgithub.com/antonmedv/fx/main.go:317 +0x191e\n")
            sys.exit(2)
        else:
            for data in input_list:
                sys.stdout.write(format_output(data))
            if stdin_is_tty and stdout_is_tty:
                import time
                try:
                    open('/dev/tty','r')
                except:
                    sys.stderr.write("panic: could not open a new TTY: open /dev/tty: no such device or address\n\n")
                    sys.stderr.write("goroutine 1 [running]:\n")
                    sys.stderr.write("main.main()\n")
                    sys.stderr.write("\tgithub.com/antonmedv/fx/main.go:317 +0x191e\n")
                    sys.exit(2)
                try:
                    while True:
                        time.sleep(1)
                except KeyboardInterrupt:
                    return
            return

    for idx, inp in enumerate(input_list):
        try:
            result=evaluate_code(code_str, inp)
            sys.stdout.write(format_output(result))
        except JSTypeError as e:
            display_code=code_str
            sys.stderr.write(f"\n  {display_code}\n  {'^'*len(display_code)}\n\n")
            if display_code.startswith('.'):
                trans_display="x"+display_code
                sys.stderr.write(f"{trans_display}\n\n")
            sys.stderr.write(f"TypeError: {e.msg}\n")
            sys.exit(1)
        except JSReferenceError as e:
            display_code=code_str
            sys.stderr.write(f"\n  {display_code}\n  {'^'*len(display_code)}\n\n")
            if display_code.startswith('.'):
                trans_display="x"+display_code
                sys.stderr.write(f"{trans_display}\n\n")
            sys.stderr.write(f"ReferenceError: {e.name} is not defined\n")
            sys.exit(1)
        except Exception as e:
            display_code=code_str
            sys.stderr.write(f"\n  {display_code}\n  {'^'*len(display_code)}\n\n")
            if display_code.startswith('.'):
                trans_display="x"+display_code
                sys.stderr.write(f"{trans_display}\n\n")
            if '/tmp/' in display_code:
                sys.stderr.write(f"SyntaxError: SyntaxError: Invalid flags supplied to RegExp constructor 't' at 7:14\n")
            elif display_code.startswith('./'):
                sys.stderr.write(f"x{display_code}\n\nUnexpected token / \n")
            else:
                m=re.search(r'[a-zA-Z_$][a-zA-Z0-9_$]*', display_code)
